"""Original critical-care questions: shock recognition and hemodynamic interpretation."""
from qbank_authoring import question,ref
rows=[]
HE=ref('ESICM circulatory shock and hemodynamic monitoring guideline: 2025','https://doi.org/10.1007/s00134-025-08137-z')
SS=ref('Surviving Sepsis Campaign adult guideline: 2026','https://sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines-for-management-of-sepsis-and-septic-shock-2026')
CS=ref('ACC cardiogenic shock guidance: 2025','https://doi.org/10.1016/j.jacc.2025.02.018')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A patient has BP 118/72 mmHg after initial resuscitation but remains confused, mottled and oliguric with rising lactate. Which statement is most accurate?', 'Normal arterial pressure does not exclude ongoing circulatory shock',[
 ('Shock is excluded whenever systolic pressure exceeds 100 mmHg','Pressure is only one component of circulation and perfusion.'),('Oliguria proves that additional fluid is required regardless of congestion','Oliguria has several mechanisms and does not establish fluid responsiveness or tolerance.'),('A rising lactate proves a single specific shock mechanism','Lactate is a risk/perfusion-related marker with several possible mechanisms.')],
 'Shock is a failure of effective tissue perfusion, not a blood-pressure cutoff alone','**Compensatory vasoconstriction or vasopressors can preserve pressure while flow and tissue perfusion remain inadequate.**',['Assess mental status, skin perfusion, urine, lactate trends and the underlying cause.','Sedation, kidney disease and drugs can alter individual markers.'], '**Reassess the circulation and organ injury directly.**',['Use bedside echo and targeted hemodynamic assessment.','Choose further fluid, pressor or inotrope treatment only after identifying the problem.'],[['Pressure','Driving force but not flow itself'],['Perfusion signs','Evidence of effective circulation'],['Shock type','Determines corrective treatment']],[HE],style='clinical_scenario')

q('MAP is 65 mmHg, CVP is 10 mmHg and cardiac output is 5 L/min. What is the approximate calculated systemic vascular resistance?', '880 dyn·s·cm−5',[
 ('440 dyn·s·cm−5','This is half the correctly calculated value.'),('1,040 dyn·s·cm−5','This neglects subtraction of CVP before applying the conversion.'),('1,760 dyn·s·cm−5','This is twice the correctly calculated value.')],
 'Calculate resistance from pressure gradient and flow','**SVR = 80 × (MAP − CVP) / cardiac output.**',['Here the gradient is 55 mmHg and 80 × 55 / 5 equals 880.','The estimate depends on accurate pressure and output measurements.'], '**Interpret the number with the phenotype and treatment exposure.**',['Vasopressors can normalize resistance without correcting the initiating cause.','A calculated SVR is not a direct test of microcirculatory flow.'],[['Pressure gradient','65 − 10 = 55 mmHg'],['Flow','5 L/min'],['SVR','880 dyn·s·cm−5']],[HE],style='clinical_scenario')

q('Cardiac output is 4.2 L/min and body surface area is 2.0 m². What is the cardiac index?', '2.1 L/min/m²',[
 ('1.05 L/min/m²','This divides by body surface area twice.'),('4.2 L/min/m²','This leaves the output unindexed.'),('8.4 L/min/m²','This multiplies rather than divides by body surface area.')],
 'Index flow to body size','**Cardiac index equals cardiac output divided by body surface area.**',['The same absolute output can represent different indexed flow in different-sized patients.','Interpretation requires perfusion, loading conditions and the clinical syndrome.'], '**Do not diagnose cardiogenic shock from one number alone.**',['A low index can occur in several shock types.','Integrate echo, filling conditions, lactate and organ function.'],[['CO','4.2 L/min'],['BSA','2.0 m²'],['CI','2.1 L/min/m²']],[HE,CS],style='clinical_scenario')

q('During passive leg raising, accurately measured stroke volume rises from 50 to 58 mL and returns to baseline when the patient is repositioned. What does this suggest?', 'Preload responsiveness under the tested conditions',[
 ('A mandatory indication to give fluid regardless of pulmonary edema','Responsiveness does not prove fluid is beneficial or tolerated.'),('A definitive diagnosis of septic shock','The maneuver does not identify the shock etiology.'),('Absence of any cardiac reserve','The observed reversible flow increase indicates a preload-related reserve.')],
 'A reversible preload challenge assesses the flow response','**An approximately sixteen-percent stroke-volume rise supports responsiveness when measured properly.**',['Use direct flow or a validated surrogate rather than pressure change alone.','The test must be performed and measured with appropriate timing and positioning.'], '**Ask whether more flow is needed and whether fluid is safe.**',['Congestion, hypoxemia and the underlying cause can make a responsive patient unsuitable for more fluid.','Repeat the assessment as conditions change.'],[['PLR','Reversible preload challenge'],['SV rise','Suggests responsiveness'],['Fluid decision','Needs need plus tolerance']],[HE],style='clinical_scenario')

q('Which condition most undermines conventional pulse-pressure-variation interpretation for fluid responsiveness?', 'Atrial fibrillation with spontaneous respiratory effort',[
 ('Controlled ventilation with a regular rhythm and appropriate tidal conditions','This is closer to the setting where the measure can be informative.'),('An arterial catheter with a verified waveform','A reliable waveform improves rather than undermines measurement.'),('Stable ventilator and vasopressor settings during the measurement','Stable conditions improve interpretation.')],
 'Dynamic indices have validity conditions','**Irregular rhythm and spontaneous breathing can make PPV misleading.**',['Low tidal volume, RV dysfunction and altered chest/abdominal mechanics also complicate interpretation.','A threshold is not universally transferable across settings.'], '**Choose a suitable alternative such as PLR with flow measurement when appropriate.**',['Verify the waveform before interpreting a derived variable.','Do not use PPV as an automatic fluid prescription.'],[['Regular controlled setting','Potentially useful'],['AF/spontaneous effort','Major limitation'],['Alternative','Reversible challenge with measured flow']],[HE])

q('A shocked patient has CVP 14 mmHg. Which interpretation is most appropriate?', 'CVP alone cannot determine whether cardiac output will increase with fluid',[
 ('The value proves fluid responsiveness','Static filling pressure is a poor stand-alone predictor of the flow response.'),('The value proves intravascular volume is adequate in every shock type','Pressure depends on ventricular function, compliance and surrounding pressure.'),('The value proves all further preload changes are ineffective','The relation between pressure and the functional response is not that simple.')],
 'Pressure is not a direct measure of circulating volume or responsiveness','**CVP reflects right-atrial pressure influenced by multiple factors.**',['Positive-pressure ventilation, RV dysfunction and venous congestion can elevate it.','The trend can help safety assessment when interpreted with the whole circulation.'], '**Use dynamic assessment and evaluate congestion.**',['A high pressure with RV failure may make more fluid harmful.','Do not attempt to normalize every patient to one CVP target.'],[['CVP','Right-atrial pressure context'],['Responsiveness','Requires flow-response assessment'],['Congestion','Important safety information']],[HE],style='clinical_scenario')

q('A septic patient has ScvO2 84% but persistent mottling, rising lactate and organ dysfunction. Which explanation is possible?', 'Impaired oxygen extraction or flow maldistribution despite a high venous saturation',[
 ('High ScvO2 guarantees adequate cellular oxygen use','A high value can occur when extraction is impaired.'),('ScvO2 directly measures every organ’s microcirculation','It is a global regional venous sample, not an organ-by-organ map.'),('The result proves that the patient has no distributive component','Distributive shock can produce a high venous saturation.')],
 'High venous oxygen is not always reassuring','**Venous saturation reflects the balance among delivery, consumption and extraction.**',['Sedation and reduced metabolic demand can also increase the value.','ScvO2 and mixed venous saturation are related but not identical measurements.'], '**Interpret the trend with perfusion and the mechanism.**',['Assess flow, oxygen content and organ status.','Do not give or withhold treatment solely to chase a saturation number.'],[['Low venous saturation','May reflect inadequate delivery or high demand'],['High saturation','Can reflect low extraction/demand'],['Clinical perfusion','Still essential']],[HE,SS],style='clinical_scenario')

q('Lactate rises shortly after epinephrine starts even as cardiac output and skin perfusion improve. Which mechanism may contribute?', 'Beta-2-mediated acceleration of glycolysis',[
 ('Lactate production can occur only during complete tissue anoxia','Adrenergic aerobic glycolysis is another mechanism.'),('Epinephrine eliminates hepatic lactate clearance in every patient','The effect is not a universal complete clearance block.'),('The lactate proves that more crystalloid is required despite congestion','A lactate rise alone does not establish a fluid indication.')],
 'Not all hyperlactatemia has the same mechanism','**Epinephrine can raise lactate through adrenergic metabolic effects.**',['Hypoperfusion, liver dysfunction, seizures and other mechanisms may still coexist.','The clinical trend determines whether the rise is benign or a warning.'], '**Assess perfusion and clearance rather than treating one value reflexively.**',['Review acid-base status, hemodynamics and organ function.','Avoid repeated fluid boluses solely to normalize a drug-related lactate.'],[['Adrenergic drive','Can increase production'],['Hypoperfusion','Still needs assessment'],['Fluid decision','Not from lactate alone']],[HE,SS],style='clinical_scenario')

q('Which bedside sign can complement lactate when following peripheral perfusion during shock resuscitation?', 'Standardized capillary refill time',[
 ('Serum ANA titer','This does not track immediate circulatory perfusion.'),('Daily body weight as the sole minute-to-minute perfusion target','Weight helps fluid balance assessment but is not a rapid perfusion measure.'),('An isolated historical ejection fraction','Prior systolic function does not establish current tissue perfusion.')],
 'Use a reproducible clinical perfusion measure','**Capillary refill can provide rapid information about peripheral perfusion.**',['Technique, ambient temperature and patient factors affect the result.','It is interpreted alongside pressure, flow, lactate and organ function.'], '**Use several complementary measures.**',['Do not let a normal skin sign exclude ongoing regional ischemia.','Avoid escalating therapy from an unstandardized isolated measurement.'],[['CRT','Peripheral perfusion clue'],['Lactate','Metabolic/perfusion context'],['Urine/mentation','Organ-level information']],[HE,SS])

q('Which imaging method is generally first-line for rapidly characterizing the hemodynamic pattern of undifferentiated shock?', 'Bedside echocardiography',[
 ('Cardiac MRI before stabilization','It can answer selected later questions but is not the routine first bedside shock tool.'),('Elective coronary CT in every patient','It does not rapidly characterize all shock mechanisms and may delay stabilization.'),('A plain abdominal film as the principal circulatory assessment','This does not assess ventricular function, filling or obstructive cardiac causes.')],
 'Identify a reversible mechanism early','**Bedside echo can assess ventricular function, pericardium and major loading patterns.**',['It is interpreted with the lung, venous and other clinical assessment.','A single view or IVC measurement is not a complete shock diagnosis.'], '**Repeat imaging after interventions or a change in condition.**',['Look for mixed mechanisms and acute mechanical complications.','Use more advanced monitoring when the question remains unresolved.'],[['Echo','Rapid hemodynamic phenotype'],['Serial assessment','Tracks treatment effects'],['Limitations','Operator and context dependent']],[HE])

q('A patient on PEEP 15 cm H2O has a distended IVC. Which interpretation is safest?', 'IVC size alone is unreliable for deciding fluid responsiveness under altered intrathoracic pressure',[
 ('A dilated IVC proves the patient can never be preload responsive','The surrounding pressure and right-heart function affect IVC appearance.'),('A dilated IVC requires diuresis in every patient','The treatment depends on the full hemodynamic mechanism.'),('PEEP has no effect on venous return or IVC interpretation','Positive intrathoracic pressure can alter both.')],
 'Do not translate one ultrasound dimension into a universal fluid decision','**IVC appearance is affected by ventilation, right-heart function and abdominal pressure.**',['The validity of respiratory variation depends on conditions.','Use dynamic flow assessment and the full cardiac/venous examination when needed.'], '**Evaluate both potential benefit and venous congestion.**',['Positive-pressure ventilation can change the shock mechanism.','A repeated focused assessment is more useful than an isolated diameter.'],[['IVC','Context-dependent finding'],['High PEEP','Changes loading and surrounding pressure'],['Decision','Integrate flow and tolerance']],[HE],style='clinical_scenario')

q('Which finding is the clearest reason to stop repeated empiric fluid challenges and reassess the strategy?', 'No meaningful flow improvement with worsening pulmonary or systemic venous congestion',[
 ('A low urine output alone before the mechanism is assessed','Oliguria does not independently prove either a need for more fluid or that all fluid must stop.'),('A mildly elevated lactate alone after epinephrine','The metabolic mechanism needs interpretation.'),('A single normal blood pressure reading','Pressure alone does not define the adequacy or safety of further treatment.')],
 'A challenge needs both an efficacy endpoint and a safety endpoint','**Fluid without flow benefit can increase edema and venous pressure.**',['The clinical goal is improved effective perfusion, not a predetermined cumulative volume.','Persistent shock may need vasopressor, inotrope, obstruction relief or source correction instead.'], '**Reassess the shock phenotype promptly.**',['Repeat echo and relevant perfusion measures.','Document the response to each intervention so ineffective treatment is not repeated.'],[['Benefit','Flow/perfusion improvement'],['Harm','Congestion or oxygenation worsening'],['No benefit plus harm','Stop and reassess']],[HE,SS])

if __name__=='__main__':print(f'Shock draft: {len(rows)} questions')
